package com.civicpulse.controller;
import com.civicpulse.entity.*; import com.civicpulse.repository.*; import com.civicpulse.service.CurrentUserService; import org.springframework.beans.factory.annotation.Value; import org.springframework.core.io.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.nio.file.*; import java.util.*;
@RestController @RequestMapping("/api/complaints") public class MediaController {
 private final ComplaintRepository complaints; private final ComplaintMediaRepository media; private final CurrentUserService current; private final Path root;
 public MediaController(ComplaintRepository c,ComplaintMediaRepository m,CurrentUserService u,@Value("${app.upload-dir:./uploads}") String dir){complaints=c;media=m;current=u;root=Paths.get(dir).toAbsolutePath().normalize();try{Files.createDirectories(root);}catch(Exception e){throw new IllegalStateException("Cannot create upload directory",e);}}
 @PostMapping(value="/{id}/media",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @PreAuthorize("hasRole('CITIZEN')") public ComplaintMedia upload(@PathVariable UUID id,@RequestParam("file") MultipartFile file){Complaint c=complaints.findById(id).orElseThrow(()->new NoSuchElementException("Complaint not found"));User u=current.get();if(!c.getCitizen().getUserId().equals(u.getUserId()))throw new SecurityException("Not complaint owner");if(file.isEmpty())throw new IllegalArgumentException("File is empty");if(file.getSize()>5*1024*1024)throw new IllegalArgumentException("File exceeds 5 MB limit");String type=Optional.ofNullable(file.getContentType()).orElse("");if(!List.of("image/jpeg","image/png","image/webp").contains(type))throw new IllegalArgumentException("Only JPEG, PNG and WebP images are accepted");String ext=type.substring(type.indexOf('/')+1).replace("jpeg","jpg");String name=UUID.randomUUID()+"."+ext;try{Files.copy(file.getInputStream(),root.resolve(name),StandardCopyOption.REPLACE_EXISTING);}catch(Exception e){throw new IllegalStateException("Could not store file",e);}ComplaintMedia cm=new ComplaintMedia();cm.setComplaint(c);cm.setUploadedBy(u);cm.setMediaType(type);cm.setFileUrl("/api/media/"+name);return media.save(cm);}
 @GetMapping("/{id}/media") public List<ComplaintMedia> list(@PathVariable UUID id){Complaint c=complaints.findById(id).orElseThrow();User u=current.get();if(u.getRole()==Role.CITIZEN&&!c.getCitizen().getUserId().equals(u.getUserId()))throw new SecurityException("Not authorized");return media.findByComplaintComplaintIdOrderByUploadedAtAsc(id);}
}
